#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

NavigationInfo {
  type "NONE"
}

DEF Gltf Inline {
  global TRUE
  url "../render/animation-step.gltf"
}

Transform {
  translation 0 0 -3
  children [
    DEF Touch TouchSensor { }
    Shape {
      appearance Appearance {
        material Material {
          transparency 0.9
        }
      }
      geometry Box {
        size 100 100 0.1
      }
    }
  ]
}

DEF Loop Script {
  inputOnly  SFTime touched
  outputOnly SFBool loop_

  url "ecmascript:
function touched (v) { loop_ = false; }
"
}

IMPORT Gltf.Timer1

ROUTE Touch.touchTime TO Loop.touched
ROUTE Loop.loop_ TO Timer1.set_loop
ROUTE Touch.touchTime TO Timer1.set_startTime

